/* Classic trap: margin + gap double-spacing */
.nav {
  display: flex;
  gap: 12px;
}

/* WRONG — adds 12px on top of the 12px gap */
.nav a {
  margin-left: 12px;
}

/* RIGHT — let gap do all the work */
.nav a {
  margin-left: 0;
}

type State = { status: 'ok'; data: string } | { status: 'err' };

async function process(s: State) {
  if (s.status !== 'ok') return;

  // s is narrowed to { status: 'ok'; data: string } here
  await fetch('/log');

  // ❌ Error: s.data doesn't exist on full union
  // (await resets narrowing for reassignable bindings)
  console.log(s.data);

  // ✅ Capture before the await
  const ok = s; // const = narrowing preserved
  await fetch('/log');
  console.log(ok.data); // fine
}

// Unhandled rejection — error middleware never fires
app.get('/user/:id', async (req, res) => {
  const user = await db.findUser(req.params.id);
  res.json(user);
});

// Fix: wrapper forwards rejections to next()
const wrap = fn => (req, res, next) =>
  Promise.resolve(fn(req, res, next)).catch(next);

app.get('/user/:id', wrap(async (req, res) => {
  const user = await db.findUser(req.params.id);
  res.json(user);
}));

Optional<String> cached = Optional.of("alice");

// expensiveDbLookup() fires even though Optional is present
String a = cached.orElse(expensiveDbLookup());

// Supplier is only invoked when Optional is empty
String b = cached.orElseGet(() -> expensiveDbLookup());

// Same trap in Map
map.getOrDefault(key, buildDefault()); // buildDefault() always called
map.computeIfAbsent(key, k -> buildDefault()); // lazy, correct

// BAD: all handles open until processAll returns
func processAll(paths []string) {
    for _, p := range paths {
        f, _ := os.Open(p)
        defer f.Close() // ← stacks, not per-iteration
        process(f)
    }
}

// Fix: closure scopes defer to one iteration
func processAll(paths []string) {
    for _, p := range paths {
        func() {
            f, _ := os.Open(p)
            defer f.Close() // ← runs when closure returns
            process(f)
        }()
    }
}

